  if (!Array.isArray(values)) {
    return [];
  }

  const result = [];
  let i = 0;

  while (i < values.length) {
    const [start, end] = values[i];

    // Reject range unless start is strictly less than end
    if (start >= end) {
      i++;
      continue;
    }

    // If result is empty or the new range starts before the last range ended,
    // we must merge.
    if (result.length === 0 || start < result[result.length - 1][1]) {
      const last = result[result.length - 1];
      const newStart = Math.min(last[0], start);
      const newEnd = Math.max(last[1], end);
      result.push([newStart, newEnd]);
    } else {
      result.push([start, end]);
    }

    i++;
  }

  return result;
};

